import click

def parse_port(v):
    p = int(v)
    if not 1 <= p <= 65535:
        raise ValueError('port must be between 1 and 65535')
    return p

@click.command()
@click.option('--port', type=parse_port)
def cmd(port):
    print('OK', port)

try:
    cmd(['--port', '70000'], standalone_mode=False)
except click.ClickException as e:
    print(e.format_message())
